package com.finsight.domain; import jakarta.persistence.*; @Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String email; String passwordHash; String role="ANALYST"; public Long getId(){return id;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getRole(){return role;} public void setEmail(String v){email=v;} public void setPasswordHash(String v){passwordHash=v;} }
